"use strict";const fs=require("fs");const path=require("path");const THRESHOLD=3;const STATE_FILE="/Users/younghwankang/WORK/WORKSPACE/KiiPS/.claude/state/.session-edits.json";const STALE_MS=30*60*1e3;function loadState(){const defaults={files:[],lastEdit:0,approved:false,sessionId:""};try{const raw=fs.readFileSync(STATE_FILE,"utf8");const parsed=JSON.parse(raw);return{...defaults,...parsed}}catch(_){return defaults}}function saveState(state){const dir=path.dirname(STATE_FILE);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(STATE_FILE,JSON.stringify(state,null,2),"utf8")}function buildWarning(files,newFile){const n=files.length;const lines=[];lines.push("");lines.push("┌─── MULTI-FILE CHANGE GATE ─────────────────────┐");lines.push(`│ ${n} unique files modified in this session.`.padEnd(51)+"│");lines.push("│                                                  │");lines.push("│ Modified files:                                  │");files.forEach((f,i)=>{const base=path.basename(f);const isNew=f===newFile;const label=isNew?`  ${i+1}. ${base}  (NEW)`:`  ${i+1}. ${base}`;lines.push(("│"+label).padEnd(51)+"│")});lines.push("│                                                  │");lines.push("│ Per anti-rationalization rules (CLAUDE.md),      │");lines.push("│ 3+ file changes need user approval.              │");lines.push("│                                                  │");lines.push(`│ Ask user: "I need to modify ${n} files.`.padEnd(51)+"│");lines.push('│ Should I continue?"'.padEnd(51)+"│");lines.push("│                                                  │");lines.push('│ User can say "approve multi-file" to suppress.   │');lines.push("└──────────────────────────────────────────────────┘");lines.push("");return lines.join("\n")}function checkMultiFile(filePath){if(filePath.includes("/.claude/")){return}const now=Date.now();let state=loadState();if(state.lastEdit&&now-state.lastEdit>STALE_MS){state={files:[],lastEdit:0,approved:false,sessionId:""};saveState(state);return}if(!state.sessionId){state.sessionId=String(now)}if(state.approved===true){if(!state.files.includes(filePath)){state.files.push(filePath)}state.lastEdit=now;saveState(state);return}if(state.files.includes(filePath)){state.lastEdit=now;saveState(state);return}state.files.push(filePath);state.lastEdit=now;saveState(state);if(state.files.length>=THRESHOLD){process.stderr.write(buildWarning(state.files,filePath))}}if(require.main===module){const chunks=[];process.stdin.setEncoding("utf8");process.stdin.on("data",chunk=>chunks.push(chunk));process.stdin.on("end",()=>{try{const input=chunks.join("");if(!input.trim()){process.exit(0)}const event=JSON.parse(input);const toolName=event.tool_name||"";const toolInput=event.tool_input||{};if(!["Edit","Write"].includes(toolName)){process.exit(0)}const filePath=toolInput.file_path;if(!filePath){process.exit(0)}checkMultiFile(filePath)}catch(_){}process.exit(0)});process.stdin.resume()}module.exports={checkMultiFile:checkMultiFile,THRESHOLD:THRESHOLD};